/// Looks a struct up by its Blender identifier (`"Object"`).
pub fn find_struct(identifier: &str) -> Option<&'static StructDef> {
    ALL_STRUCTS.binary_search_by(|s| s.identifier.cmp(identifier)).ok().map(|i| ALL_STRUCTS[i])
}

